SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'determinand_volatile', 'Flüchtige Verbindungen zu bestimmen (§8.10)', 'boolean', NULL, false, '§8.10', 'Plan 3: Treiber für die §8.10-Vorgabe (minimale Saugkraft, gefüllte Leitung, Vorlauf verwerfen) — nur dann ist die Vorgabe überhaupt anwendbar.', 'imported_unverified', '8.10       MUESTREO PARA EL CONTENIDO DE COMPUESTOS VOLÁTILES

