SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'A'), 'sites_1', 'Probenahmestellen (Situationstyp je Stelle)', 'json', NULL, false, '§8.1, §9, §10, §11, §12, §13', 'Plan 3: eine Zeile je Probenahmestelle — §8.1 „la red de muestreo puede tener cualquier forma desde un solo sitio hasta todo un desagüe de río“; je Zeile greifen die situationsspezifischen Prüfungen aus §9 bis §13 (Ablösung der Einzel-Skalare STAGED, iso5667_1-D-5 … D-16).', 'imported_unverified', '8.2        IDENTIFICACIÓN DE LA LOCALIZACIÓN DEL MUESTREO

La identificación de la localización del muestreo permite tomar muestras comparativas en otros momentos. En la mayoría de las situaciones de
ríos, las localizaciones del muestreo se pueden fijar fácilmente mediante la referencia a características del banco ribereño.

En playas descubiertas de estuarios y costas, las localizaciones de muestreo análogamente se pueden relacionar con un objeto estático fácilmente
reconocible. Para el muestreo desde un bote en estas situaciones, se deben utilizar métodos instrumentales para la identificación de la
localización. Las referencias de mapas u otras formas estándar de referencia pueden ser muy valiosas.', 'register', '{"title":"Probenahmestellen (§8.1 / §9 – §13)","subtitle":"Je Stelle der Gewässersituationstyp; die situationsspezifischen Spalten erscheinen nach der Wahl.","add_label":"+ Probenahmestelle","columns":[{"key":"kennung","label":"Kennung / ID","type":"text","required":true,"width":"9rem","aria_label":"Kennung der Probenahmestelle"},{"key":"situation_type","label":"Gewässersituationstyp","type":"enum","required":true,"discriminator":true,"options":["precipitation","estuary_coastal_sea","river_stream","canal","reservoir_lake","groundwater","sediment","drinking_water","bathing_water","industrial_supply","boiler_system","cooling_system","commercial_effluent","wastewater","wastewater_sludge","stormwater"],"option_labels":{"precipitation":"Niederschlag (§9.1)","estuary_coastal_sea":"Ästuar / Küste / Meer (§9.2)","river_stream":"Fluss / Bach (§9.3)","canal":"Kanal (§9.4)","reservoir_lake":"Speicher / See (§9.5)","groundwater":"Grundwasser (§9.6)","sediment":"Sediment (§9.7)","drinking_water":"Trinkwasser (§9.8)","bathing_water":"Badegewässer (§9.9)","industrial_supply":"Industrielle Versorgung (§10.1)","boiler_system":"Kesselanlage (§10.2)","cooling_system":"Kühlsystem (§10.2.4)","commercial_effluent":"Gewerbliches Abwasser (§11)","wastewater":"Abwasser (§12)","wastewater_sludge":"Klärschlamm (§12.1.2)","stormwater":"Regen-/Mischwasserentlastung (§13)"},"aria_label":"Gewässersituationstyp der Probenahmestelle"},{"key":"location_identified","label":"Stelle identifiziert","type":"boolean","aria_label":"Probenahmestelle nach §8.2 eindeutig identifiziert"},{"key":"flow_character","label":"Strömungscharakter","type":"enum","options":["turbulent_well_mixed","laminar_pipe","reverse_flow"],"option_labels":{"turbulent_well_mixed":"turbulent, gut durchmischt (§8.3)","laminar_pipe":"laminar / Rohrströmung (§8.3)","reverse_flow":"„flujo inverso“ (§8.4)"},"aria_label":"Strömungscharakter an der Probenahmestelle (§8.3)"},{"key":"weather","label":"Witterung","type":"text","aria_label":"Witterungsbedingungen bei der Probenahme (§8.13)"},{"key":"depth_below_ground_m","label":"Entnahmetiefe u. GOK (m)","type":"number","unit":"m","min":0,"visible_when":"situation_type == ''groundwater''","aria_label":"Entnahmetiefe unter Geländeoberkante in m (§9.6.2)"},{"key":"well_purged","label":"Brunnen abgepumpt","type":"boolean","visible_when":"situation_type == ''groundwater''","aria_label":"Brunnen vor der Probenahme abgepumpt (§9.6.2)"},{"key":"upstream_downstream","label":"Ober-/unterstrom beprobt","type":"boolean","visible_when":"situation_type == ''river_stream''","aria_label":"Probenahme ober- und unterstrom der Einleitung (§9.3.2)"},{"key":"cooling_type","label":"Kühlsystemtyp","type":"enum","options":["open_evaporative","once_through","closed_circuit"],"visible_when":"situation_type == ''cooling_system''","option_labels":{"open_evaporative":"Offene Verdunstung (Evaporación abierta)","once_through":"Durchlauf (Un solo paso)","closed_circuit":"Geschlossener Kreislauf (Circuito cerrado)"},"aria_label":"Kühlsystemtyp nach §10.2.4"},{"key":"manhole_no_entry","label":"Schacht ohne Einstieg beprobbar","type":"boolean","visible_when":"situation_type == ''commercial_effluent''","aria_label":"Inspektionsschacht so ausgebildet, dass ohne Einstieg beprobt werden kann (§11.1)"},{"key":"composite_multipoint","label":"Misch-/Mehrpunktprobe","type":"boolean","visible_when":"situation_type == ''wastewater''","aria_label":"Zwei bis drei Routineproben an verschiedenen Punkten gemischt (§12.1.1)"},{"key":"sludge_pipe_dn_mm","label":"Schlammleitung DN (mm)","type":"number","unit":"mm","min":0,"visible_when":"situation_type == ''wastewater_sludge''","aria_label":"Durchmesser der Schlamm-Probenahmeleitung in mm (§12.1.2)"},{"key":"sludge_pipe_ok","label":"§12.1.2","type":"derived","expr":"if(sludge_pipe_dn_mm >= lookup(''S12_1_2'', ''sludge_pipe'', ''min_diameter_mm''), 1, 0)","display":"badge","visible_when":"situation_type == ''wastewater_sludge''","value_labels":{"0":"§12.1.2 unter 50 mm oder nicht eingetragen","1":"§12.1.2 ≥ 50 mm erfüllt"}},{"key":"flow_proportional","label":"Durchflussproportional","type":"boolean","visible_when":"situation_type == ''stormwater''","aria_label":"Durchflussproportionale Probenahme vorgesehen (§13)"}],"footer":["sites_count"]}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'sites_1') AND w.code = 'ISO-5667-1-05' AND s.code = 'ISO-5667-1';
