INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'sampling_time_note', 'Probenahmezeitpunkte bei ausgeprägter Variabilität (§16.5)', 'text', NULL, false, '§16.5', 'Plan 3: Begründung der gewählten Probenahmezeitpunkte, wenn das Variabilitätsprofil weite und schnelle Schwankungen ausweist — §16.5: „Si ocurren variaciones cíclicas, los tiempos de muestreo son importantes“. Der Treiber variability_profile kennt heute keinen Token „cyclic“ (iso5667_1-D-1).', 'imported_unverified', '16.5       VARIACIONES ALEATORIAS Y SISTEMÁTICAS DE LA CALIDAD DEL AGUA

Las variaciones aleatorias comúnmente tienen una distribución normal o una distribución lognormal. Las variaciones sistemáticas pueden ser
tendencias o variaciones cíclicas, y se pueden presentar combinaciones de las dos. La naturaleza de la variabilidad puede ser diferente para
factores determinantes diferentes de la misma agua.

Si las variaciones aleatorias son dominantes, los tiempos de muestreo generalmente no son importantes estadísticamente, aunque sí pueden ser
importantes para propósitos de control de calidad. Si ocurren variaciones cíclicas, los tiempos de muestreo son importantes, bien sea para cubrir
todo el ciclo o para detectar concentraciones de interés máximas o mínimas. Los tiempos de muestreo deben ser espaciados en forma
aproximadamente igual a lo largo de los períodos de tendencia. En cada una de las situaciones anteriores, el número de muestras debe ser regido
en gran parte por las consideraciones estadísticas indicadas antes.', 'scalar', NULL, NULL, 'variability_profile == ''wide_rapid''', NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'sampling_time_note') AND w.code = 'ISO-5667-1-06' AND s.code = 'ISO-5667-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'D'), 'abnormal_conditions', 'Anormale Bedingungen (§17)', 'boolean', NULL, false, '§17', 'Plan 3: Treiber für die §17-Frequenzerhöhung (Anfahren einer Prozessanlage, Hochwasser, Algenblüte). Die Sichtbarkeitsregel auf abnormal_frequency_increase ist STAGED (CR-022 liest das Symbol — iso5667_1-G-3).', 'imported_unverified', '17.        VARIABILIDAD ANORMAL

Es posible que se necesite incrementar la frecuencia del muestreo mientras persistan condiciones anormales, por ejemplo durante la puesta en
marcha de una planta por procesos, durante las condiciones de inundación en un río, o en tiempos de florecimiento de algas. Al calcular las
tendencias a largo plazo, los resultados obtenidos a partir de estas muestras sólo se usarán si se prevé una frecuencia incrementada.', 'attestation', NULL, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'abnormal_conditions') AND w.code = 'ISO-5667-1-06' AND s.code = 'ISO-5667-1';
INSERT INTO fields (worksheet_template_id, section_id, symbol, label_de, data_type, unit, is_required, clause_reference, description, verification_status, verification_quote, widget, ui_config, lookup, visible_when, enum_values, order_index, active)
SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'B'), 'historical_results', 'Vorliegende Einzelergebnisse x_i', 'json', NULL, false, '§16.4', 'Plan 3: eine Zeile je Einzelergebnis x_i aus der Vorerkundung — §16.4: „Para cierto número de resultados n, tomados al azar, las estimaciones … son la media aritmética, X, y s respectivamente“. Ersetzt die skalare Einzelwerteingabe x_i (Ablösung STAGED, iso5667_1-D-17).', 'imported_unverified', '16.4       DETERMINACIÓN DEL INTERVALO DE CONFIANZA Y DEL NÚMERO DE MUESTRAS

Para cierto número de resultados n, tomados al azar, las estimaciones de la media aritmética verdadera X y la desviación estándar, σ, son la
media aritmética, X , y s respectivamente de acuerdo con la siguiente fórmula:', 'register', '{"title":"Einzelergebnisse x_i (§16.4)","subtitle":"§16.4: x̄, n und s werden aus diesen Zeilen berechnet; s ist die Stichproben-Standardabweichung mit dem gedruckten Nenner n − 1.","add_label":"+ Einzelergebnis","columns":[{"key":"kennung","label":"Probe","type":"text","width":"8rem","aria_label":"Kennung der Einzelprobe"},{"key":"datum","label":"Datum","type":"date","width":"10rem","aria_label":"Datum der Probenahme"},{"key":"x_value","label":"x_i","type":"number","required":true,"unit":"mg/l","aria_label":"Einzelergebnis x_i in mg/l"}],"sum_column":{"key":"x_value","label":"Σ x_i","unit":"mg/l"},"footer":["n_hist","x_mean_calc","s_calc"]}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
