SELECT w.id, (SELECT ws.id FROM worksheet_sections ws WHERE ws.worksheet_template_id = w.id AND ws.code = 'E'), 'flow_measurements', 'Durchflussmessungen je Messstelle', 'json', NULL, false, '§19.1, §21', 'Plan 3: eine Zeile je Messstelle mit Strömungsaspekt und gewähltem Verfahren; die Spalte §21 prüft gegen den gedruckten Verfahrenskatalog S21 (Ablösung der Skalare flow_measurement_method / flow_measurement_mode / flow_velocity / discharge_rate / flow_aspect STAGED, iso5667_1-D-18 … D-22).', 'imported_unverified', 'Hay tres aspectos del flujo que es necesario medir, a saber,

           a)         Dirección del flujo.

           b)         Velocidad del flujo.

           c)         Tasa de flujo.', 'register', '{"title":"Durchflussmessungen (§19.1 / §21)","subtitle":"§19.1: „Hay tres aspectos del flujo que es necesario medir“ — Richtung, Geschwindigkeit, Abfluss; §21 listet je Aspekt die verfügbaren Verfahren.","add_label":"+ Messstelle","columns":[{"key":"kennung","label":"Messstelle","type":"text","required":true,"width":"9rem","aria_label":"Kennung der Durchflussmessstelle"},{"key":"aspect","label":"Strömungsaspekt","type":"enum","required":true,"discriminator":true,"options":["direction","velocity","discharge"],"option_labels":{"direction":"Richtung (Dirección del flujo)","velocity":"Geschwindigkeit (Velocidad del flujo)","discharge":"Abfluss (Tasa de flujo)"},"aria_label":"Zu messender Strömungsaspekt (§19.1)"},{"key":"method","label":"Verfahren","type":"enum","required":true,"options":["drogue","float_trawl","chemical_tracer","microbiological_tracer","radioactive_tracer","current_meter","ultrasonic","electromagnetic","pneumatic","weir_level","venturi","orifice_plate","pumping_rate","dilution_gauging","mechanical"],"sort_by_label":true,"option_labels":{"drogue":"Dragas (Schleppkörper) — §21.2 a)","float_trawl":"Flotadores y barcos con redes rastreras — §21.2 b)","chemical_tracer":"Trazas químicas (incl. tinturas) — §21.2 c)","microbiological_tracer":"Trazadores microbiológicos — §21.2 d)","radioactive_tracer":"Trazadores radiactivos — §21.2 e)","current_meter":"Medidores de la corriente — §21.3 a)","ultrasonic":"Técnicas ultrasónicas — §21.3 b) / §21.4 d) 4)","electromagnetic":"Técnicas electromagnéticas — §21.3 c) / §21.4 d) 4)","pneumatic":"Técnicas neumáticas — §21.3 d)","weir_level":"Wasserstand über Einengung (Wehr) — §21.4 c)","venturi":"Venturi-Düse — §21.4 d) 1)","orifice_plate":"Blende (placa de orificio) — §21.4 d) 2)","pumping_rate":"Pumpenförderstrom × Dauer — §21.4 d) 3)","dilution_gauging":"Calibrador de dilución — §21.4 e)","mechanical":"Medios mecánicos directos — §21.4 b)"},"aria_label":"Durchflussmessverfahren nach §21"},{"key":"method_ok","label":"§21","type":"derived","expr":"if(lookup(''S21'', aspect, method, ''valid'') == 1, 1, 0)","display":"badge","value_labels":{"0":"§21: Verfahren für diesen Aspekt nicht gedruckt","1":"§21: Verfahren für diesen Aspekt gedruckt"}},{"key":"mode","label":"Messmodus","type":"enum","options":["discrete","continuous"],"option_labels":{"discrete":"diskret (discretas — Flotadores, Direktanzeige)","continuous":"kontinuierlich (continuas — Durchflussmesser)"},"aria_label":"Messmodus nach §21.1"},{"key":"velocity_measured","label":"v (m/s)","type":"number","unit":"m/s","visible_when":"aspect IN {''velocity'', ''discharge''}","aria_label":"Gemessene Strömungsgeschwindigkeit in m/s"},{"key":"discharge_measured","label":"Q (m³/s)","type":"number","unit":"m3/s","visible_when":"aspect == ''discharge''","aria_label":"Gemessener Abfluss in m³/s"}],"footer":["flow_measurements_count"]}'::jsonb, NULL, NULL, NULL, (SELECT COALESCE(MAX(order_index), 0) + 1 FROM fields f3 WHERE f3.worksheet_template_id = w.id), true
FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE NOT EXISTS (SELECT 1 FROM fields f2 WHERE f2.worksheet_template_id = w.id AND f2.symbol = 'flow_measurements') AND w.code = 'ISO-5667-1-08' AND s.code = 'ISO-5667-1';
